import unittest
from candidate import triangle_area

class TestTriangleArea(unittest.TestCase):
    def test_valid_triangle_positive_integers(self):
        self.assertAlmostEqual(triangle_area(3, 4, 5), 6.00)

    def test_valid_triangle_floats(self):
        self.assertAlmostEqual(triangle_area(5.5, 6.0, 7.0), 14.70)

    def test_valid_triangle_small_numbers(self):
        self.assertAlmostEqual(triangle_area(1.1, 1.1, 1.1), 0.49)

    def test_valid_triangle_equilateral(self):
        self.assertAlmostEqual(triangle_area(2, 2, 2), 1.73)

    def test_valid_triangle_isosceles(self):
        self.assertAlmostEqual(triangle_area(5, 5, 6), 12.00)

    def test_invalid_triangle_sum_violations(self):
        self.assertEqual(triangle_area(1, 2, 10), -1)

    def test_invalid_triangle_zero_side(self):
        self.assertEqual(triangle_area(0, 5, 5), -1)

    def test_invalid_triangle_negative_side(self):
        self.assertEqual(triangle_area(-1, 2, 3), -1)

    def test_invalid_triangle_zero_or_negative_floats(self):
        self.assertEqual(triangle_area(0.5, -1.5, 2.5), -1)

    def test_invalid_triangle_zero_or_negative_large_numbers(self):
        self.assertEqual(triangle_area(1000000, -1000000, 1000000), -1)

    def test_edge_case_very_small_numbers(self):
        self.assertAlmostEqual(triangle_area(0.0001, 0.0001, 0.0001), 0.00)

    def test_edge_case_very_large_numbers(self):
        self.assertAlmostEqual(triangle_area(1000000, 1000000, 1000000), 430000.00)

    def test_none_input(self):
        with self.assertRaises(TypeError):
            triangle_area(None, 3, 4)

    def test_wrong_type_input(self):
        with self.assertRaises(TypeError):
            triangle_area("3", 4, 5)

    def test_mixed_types_valid(self):
        self.assertAlmostEqual(triangle_area(3.5, 4, 5), 6.00)

    def test_mixed_types_invalid(self):
        self.assertEqual(triangle_area(3, "4", 5), -1)

    def test_identical_sides(self):
        self.assertAlmostEqual(triangle_area(2, 2, 2), 1.73)

    def test_minimal_valid_triangle(self):
        self.assertAlmostEqual(triangle_area(1.0001, 1.0001, 1.9999), 0.4999)
